add_filter( 'woocommerce_default_address_fields', 'perfectpixel_reorder_address_fields', 9999 );

function perfectpixel_reorder_address_fields( $fields ) {
	// WooCommerce defaults: first_name 10, last_name 20, company 30, country 40,
	// address_1 50, address_2 60, city 70, state 80, postcode 90.
	$priorities = array(
		'address_1' => 40,
		'address_2' => 50,
		'postcode'  => 60,
		'city'      => 70,
		'state'     => 80,
		'country'   => 90,
	);

	foreach ( $priorities as $key => $priority ) {
		if ( isset( $fields[ $key ] ) ) {
			$fields[ $key ]['priority'] = $priority;
		}
	}
	return $fields;
}
